head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL05103_TIP";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05103_tip.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        if ($c.util.getCookie('alertListPre1Day') !== 'alertListPre1Day' && $c.util.getCookie('alertListPre1Week') !== 'alertListPre1Week') {
            $c.util.getComponent('divAlertListPre').removeClass('pop_wrap');
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05103_tip.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_extend1Week_onclick
 * @description btn_extend1Week 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_extend1Week_onclick = function(e){
    try {
        scwin.extend1Week()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05103_tip.btn_extend1Week_onclick' }); }
};

/**
 * @method
 * @name btn_extend1Day_onclick
 * @description btn_extend1Day 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_extend1Day_onclick = function(e){
    try {
        scwin.extend1Day()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil05103_tip.btn_extend1Day_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name extend1Day
 * @description extend1 Day 처리
 * @returns {void}
 * @hidden N
 */
scwin.extend1Day = function () {
    $c.util.setSessionStorage("alertListPre1Day", "alertListPre1Day");
    hideLayer("#divAlertListPre");
};

/**
 * @method
 * @name extend1Week
 * @description extend1 Week 처리
 * @param {*} chkVal chkVal
 * @returns {void}
 * @hidden N
 */
scwin.extend1Week = function (chkVal) {
    $c.util.setCookie("alertListPre1Week", "alertListPre1Week", 6);
    hideLayer("#divAlertListPre");
};
